package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.ParsedDocument;import org.springframework.stereotype.Component;import java.util.*;
@Component public class QaPairChunkingStrategy implements ChunkingStrategy {public String code(){return "QA_PAIR";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){List<ChunkFragment>out=new ArrayList<>();String[] lines=d.getPlainText().split("\\R");for(int i=0;i<lines.length;i++){String line=lines[i].trim();if(line.matches("(?i)^(q|question|问题)[：:].*")){StringBuilder pair=new StringBuilder(line);if(i+1<lines.length)pair.append('\n').append(lines[++i].trim());out.addAll(ChunkingSupport.windows(pair.toString(),p,null,d.getTitle(),null,null));}}return out.isEmpty()?ChunkingSupport.windows(d.getPlainText(),p,null,d.getTitle(),null,null):out;}}
